import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"Mobile apps","description":"Android sideload is a single file. F-Droid is a listing. This does not replace App Store / Play review.","frontmatter":{"title":"Mobile apps","description":"Android sideload is a single file. F-Droid is a listing. This does not replace App Store / Play review."},"headers":[],"relativePath":"en/guide/scenarios/mobile.md","filePath":"en/guide/scenarios/mobile.md","lastUpdated":1790057721000}`),a={name:`en/guide/scenarios/mobile.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="mobile-apps" tabindex="-1">Mobile apps <a class="header-anchor" href="#mobile-apps" aria-label="Permalink to “Mobile apps”">​</a></h1><h2 id="package-shape" tabindex="-1">Package shape <a class="header-anchor" href="#package-shape" aria-label="Permalink to “Package shape”">​</a></h2><p>Android <strong>sideload</strong> publishes the APK as a <strong>single file</strong> (matrix single-file). Official SDKs are not APK installers: you must supply a Replacer. Compare and download remain <strong>POST</strong> check plus a SHA-256 object.</p><p>An F-Droid subscription is a separate store listing (<code>fdroid</code>), not the native JSON URL. Index documents:</p><div class="vp-code-group"><div class="tabs"><input type="radio" name="group-12" id="tab-13" checked><label data-title="index-v1" for="tab-13">index-v1</label><input type="radio" name="group-12" id="tab-14"><label data-title="index-v2" for="tab-14">index-v2</label></div><div class="blocks"><div class="language-text active line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://updates.example.com/api/v1/projects/myapp/store/fdroid/stable/index-v1.json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-text line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://updates.example.com/api/v1/projects/myapp/store/fdroid/stable/index-v2.json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></div></div><p>Console: <strong>Settings → Store listings</strong> → <strong>New listing</strong>, protocol <code>fdroid</code>. Unknown paths (for example <code>index.xml</code>) are plaintext 404. Official SDKs do <strong>not</strong> read the F-Droid index.</p><p>iPhone enterprise / sideload can use native JSON or a custom drop; that does <strong>not</strong> replace App Store review. Play / App Store private protocols are out of scope.</p><h2 id="failures" tabindex="-1">Failures <a class="header-anchor" href="#failures" aria-label="Permalink to “Failures”">​</a></h2><p>Missing listing → plaintext 404. Native check codes: <a href="/en/faq/errors">FAQ · Error codes</a>.</p><p>Related: <a href="/en/guide/features/store">Store listings</a>, <a href="./desktop">Desktop</a>.</p>`,10)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};